import{_ as i,o as s,c as t,a2 as e}from"./chunks/framework.Cvf4Fkn6.js";const k=JSON.parse('{"title":"快速开始","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md","lastUpdated":1794563471000}'),l={name:"guide/getting-started.md"};function n(h,a,r,p,o,d){return s(),t("div",null,[...a[0]||(a[0]=[e(`<h1 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h1><p>从下载安装到完成首次授权，大约需要两分钟。</p><hr><h2 id="_1-下载安装" tabindex="-1">1. 下载安装 <a class="header-anchor" href="#_1-下载安装" aria-label="Permalink to &quot;1. 下载安装&quot;">​</a></h2><ol><li>前往 <a href="https://github.com/crazy-airhead/WTidy/releases/latest" target="_blank" rel="noreferrer">Releases 最新版本</a>，下载 <code>WTidy-vX.Y.Z-macos-arm64.zip</code></li><li>解压得到 <code>WTidy.app</code>，拖入「应用程序」文件夹</li><li>双击启动，菜单栏出现 WTidy 图标即运行中（WTidy 是菜单栏应用，没有 Dock 图标和主窗口）</li></ol><blockquote><p><strong>macOS 未公证提示</strong>：应用为 ad-hoc 签名、未做 Apple 公证，首次打开若提示无法验证开发者，<strong>右键 App →「打开」</strong>，或执行 <code>xattr -d com.apple.quarantine /Applications/WTidy.app</code> 后再打开。</p></blockquote><hr><h2 id="_2-首次使用-辅助功能授权" tabindex="-1">2. 首次使用：辅助功能授权 <a class="header-anchor" href="#_2-首次使用-辅助功能授权" aria-label="Permalink to &quot;2. 首次使用：辅助功能授权&quot;">​</a></h2><p>WTidy 依赖 macOS 辅助功能（Accessibility）API 监听窗口拖拽、读取与移动窗口，首次启动会自动弹出引导页：</p><ol><li>点引导页中的授权入口（或手动前往 <strong>系统设置 → 隐私与安全性 → 辅助功能</strong>）</li><li>把 WTidy 加入并打开开关</li><li>回到引导页，条目自动打勾后点「开始使用」</li></ol><blockquote><p><strong>重新构建 / 覆盖安装后需要重新授权</strong>：macOS 以代码签名识别辅助功能授权，ad-hoc 签名每次构建都会变——从源码重新安装后，需在辅助功能列表中先移除旧条目再重新添加。</p></blockquote><hr><h2 id="_3-试一下" tabindex="-1">3. 试一下 <a class="header-anchor" href="#_3-试一下" aria-label="Permalink to &quot;3. 试一下&quot;">​</a></h2><p>按住任意窗口的标题栏拖动：</p><ul><li>屏幕上浮现<strong>布局图标条</strong>，悬停图标后整屏显示落点预览</li><li><strong>瞄准在图标内完成</strong>：「左右半屏」图标偏左 = 左半、偏右 = 右半，单图标即可选区</li><li>松手在图标上即吸附；移入屏内松手为精确选区；其他位置松手 = 正常拖拽，不打扰</li></ul><p>也可以不动鼠标，直接用快捷键：<code>⌥⌘←</code> 把前台窗口吸到左半屏。全部快捷键见<a href="./hotkeys.html">快捷键</a>。</p><hr><h2 id="_4-与-macos-原生分屏共存" tabindex="-1">4. 与 macOS 原生分屏共存 <a class="header-anchor" href="#_4-与-macos-原生分屏共存" aria-label="Permalink to &quot;4. 与 macOS 原生分屏共存&quot;">​</a></h2><p>macOS 15+ 自带「窗口拖到屏幕边缘磁贴」，与 WTidy 可共存：WTidy 由顶部布局图标条触发，原生磁贴由屏幕边缘触发，二者入口不同。若嫌干扰，可在 <strong>系统设置 → 桌面与程序坞</strong> 中关闭「将窗口拖到屏幕边缘时平铺」。</p><hr><h2 id="_5-从源码构建-进阶" tabindex="-1">5. 从源码构建（进阶） <a class="header-anchor" href="#_5-从源码构建-进阶" aria-label="Permalink to &quot;5. 从源码构建（进阶）&quot;">​</a></h2><p>仅需 Command Line Tools（无需 Xcode）：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git@github.com:crazy-airhead/WTidy.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> WTidy</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swift</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Release</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # 编译</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scripts/build-app.sh</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # 组装 + ad-hoc 签名 → build/WTidy.app</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scripts/build-app.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --install</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # 安装到 /Applications 并启动</span></span></code></pre></div><p>运行测试（CLT 的 Testing 宏插件在子目录，需显式指定路径）：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swift</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Xswiftc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -plugin-path</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Xswiftc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /Library/Developer/CommandLineTools/usr/lib/swift/host/plugins/testing</span></span></code></pre></div><hr><h2 id="_6-下一步" tabindex="-1">6. 下一步 <a class="header-anchor" href="#_6-下一步" aria-label="Permalink to &quot;6. 下一步&quot;">​</a></h2><ul><li><a href="./drag-snap.html">拖拽分屏与布局条</a>：招牌交互的完整细节</li><li><a href="./layouts.html">布局自定义</a>：编辑出自己的布局</li><li><a href="./hotkeys.html">快捷键</a>：为常用区域录制专属快捷键</li><li><a href="./faq.html">常见问题</a>：图标条不出现、授权失效等排查</li></ul>`,28)])])}const g=i(l,[["render",n]]);export{k as __pageData,g as default};
